function nearestPlayer(team,x,y,includeKeeper=false){let list=team===0?game.home:game.away;let best=null,d=1e9;for(const p of list){if(p.keeper&&!includeKeeper)continue;const z=Math.hypot(p.x-x,y-p.y);if(z<d){best=p;d=z}}return best}
function kick(p,angle,power=330){if(!game)return;let b=game.ball;b.owner=null;b.x=p.x;b.y=p.y;b.vx=Math.cos(angle)*power;b.vy=Math.sin(angle)*power;game.message='';}
function tryShoot(){if(!game||game.paused||game.ended)return;const p=game.home[game.selected];if(game.ball.owner&&game.ball.owner.team===0){kick(p,Math.atan2(360-p.y,1168-p.x),440);return}if(dist(p,game.ball)<30){kick(p,Math.atan2(360-p.y,1168-p.x),440)}}
function tryPass(){if(!game||game.paused||game.ended)return;const p=game.home[game.selected];if(game.ball.owner?.team!==0&&dist(p,game.ball)>22)return;let mate=game.home.filter(q=>q!==p&&!q.keeper).sort((a,b)=>Math.hypot(b.x-p.x,b.y-p.y*.01)-Math.hypot(a.x-p.x,a.y-p.y*.01))[0];if(mate)kick(p,Math.atan2(mate.y-p.y,mate.x-p.x),300)}
function switchPlayer(){if(!game)return;let b=game.ball;let n=nearestPlayer(0,b.x,b.y);if(n)game.selected=game.home.indexOf(n)}
function controls(){let dx=0,dy=0;if(keys.ArrowLeft||keys.a||pointer?.left)dx--;if(keys.ArrowRight||keys.d||pointer?.right)dx++;if(keys.ArrowUp||keys.w||pointer?.up)dy--;if(keys.ArrowDown||keys.s||pointer?.down)dy++;return {dx,dy}}
function update(dt){if(screen!=='game'||!game||game.paused||game.ended)return;dt=Math.min(dt,.04);let g=game,b=g.ball;g.elapsed+=dt;if(!g.penalty)g.time=Math.max(0,g.time-dt);if(g.time===0){g.ended=true;g.message=g.score[0]===g.score[1]?'EMPATE!':'FIM DE JOGO';return}
let controlled=g.home[g.selected],input=controls(),mag=Math.hypot(input.dx,input.dy);if(mag){input.dx/=mag;input.dy/=mag}let sprint=!!(keys.Shift||pointer?.sprint),speed=sprint&&g.stamina>0?218:152;g.stamina=clamp(g.stamina+(sprint&&mag?-25:12)*dt,0,100);controlled.vx=input.dx*speed;controlled.vy=input.dy*speed;controlled.x+=controlled.vx*dt;controlled.y+=controlled.vy*dt;
for(let i=0;i<g.home.length;i++){let p=g.home[i];if(p===controlled)continue;let targetX=340+(i%2)*62,targetY=225+Math.floor(i/2)*83;if(b.owner?.team===1){targetX=clamp(b.x-150,220,570);targetY=clamp(b.y+(i%2?70:-70),195,565)}else if(b.owner?.team===0){targetX=clamp(b.x+80,300,800);targetY=clamp(b.y+(i%2?65:-65),190,575)}p.x+=(targetX-p.x)*dt*.48;p.y+=(targetY-p.y)*dt*.48}
for(let i=0;i<g.away.length;i++){let p=g.away[i];if(p.keeper){let ty=clamp(b.y,292,428);p.y+=(ty-p.y)*dt*.55;continue}let targetX=clamp(b.x+45,620,1040),targetY=b.y+(i%2?50:-50);if(b.owner?.team===1){targetX=clamp(1000-i*16,680,1080);targetY=clamp(b.y+(i%2?64:-64),185,580)}p.x+=(targetX-p.x)*dt*(difficulty===2?.8:.52);p.y+=(targetY-p.y)*dt*(difficulty===2?.8:.52)}
for(const p of actorList()){p.x=clamp(p.x,126,1154);p.y=clamp(p.y,161,608)}
if(b.owner){let p=b.owner;if(p.team===0&&p===controlled){b.x=p.x+11;b.y=p.y+2}else if(p.team===1){b.x=p.x-11;b.y=p.y+2;if(Math.random()<dt*(difficulty===0?.12:.35)){kick(p,Math.atan2(360-p.y,115-p.x),difficulty===2?350:290)}}}else{b.x+=b.vx*dt;b.y+=b.vy*dt;b.vx*=Math.pow(.985,dt*60);b.vy*=Math.pow(.985,dt*60);if(b.y<156||b.y>613)b.vy*=-.75;b.y=clamp(b.y,156,613);if(Math.hypot(b.vx,b.vy)<19)b.vx=b.vy=0;
if(b.x<108&&b.y>302&&b.y<418){g.score[1]++;goal(1)}else if(b.x>1172&&b.y>302&&b.y<418){g.score[0]++;goal(0)}else{if(b.x<118||b.x>1162)b.vx*=-.75;b.x=clamp(b.x,112,1168);let candidates=actorList().filter(p=>!p.keeper);for(const p of candidates){if(dist(p,b)<p.r+b.r+4&&Math.hypot(b.vx,b.vy)<155){b.owner=p;break}}}}
if(g.messageTimer>0)g.messageTimer-=dt}
